import{_ as e,c as t,o as a,ag as l}from"./chunks/framework.ymCRTBvy.js";const p=JSON.parse('{"title":"📘 《iOS纯代码开发：UIKit、网络与数据持久化实战》","description":"","frontmatter":{},"headers":[],"relativePath":"swift/uikit/uikit_networking_persistence/index.md","filePath":"swift/uikit/uikit_networking_persistence/index.md"}'),r={name:"swift/uikit/uikit_networking_persistence/index.md"};function n(o,i,s,_,c,d){return a(),t("div",null,i[0]||(i[0]=[l('<h1 id="📘-《ios纯代码开发-uikit、网络与数据持久化实战》" tabindex="-1">📘 《iOS纯代码开发：UIKit、网络与数据持久化实战》 <a class="header-anchor" href="#📘-《ios纯代码开发-uikit、网络与数据持久化实战》" aria-label="Permalink to &quot;📘 《iOS纯代码开发：UIKit、网络与数据持久化实战》&quot;">​</a></h1><h2 id="📖-内容简介" tabindex="-1">📖 内容简介： <a class="header-anchor" href="#📖-内容简介" aria-label="Permalink to &quot;📖 内容简介：&quot;">​</a></h2><p>本书是一本面向初中级iOS开发者的全面实战指南，系统讲解如何使用纯代码方式构建完整的iOS应用。全书从零开始，循序渐进地带领读者掌握UIKit界面开发、网络通信与数据持久化三大核心技能，涵盖从基础控件到复杂架构的完整开发流程。</p><p>不同于依赖Storyboard的传统开发方式，本书专注于纯代码编程实践，培养读者对iOS开发底层原理的深入理解。通过详实的代码示例和项目实战，帮助读者建立坚实的开发基础，掌握现代化iOS应用开发的全套技术栈。</p><p>本书包含20个精心设计的章节，每章都配有可直接上手的实战案例，从简单的界面搭建到复杂的网络数据管理，逐步构建一个功能完整的新闻阅读应用，让学习过程更加贴近真实开发场景。</p><h2 id="✅-你将学到" tabindex="-1">✅ 你将学到： <a class="header-anchor" href="#✅-你将学到" aria-label="Permalink to &quot;✅ 你将学到：&quot;">​</a></h2><ul><li>熟练使用UIKit纯代码构建复杂用户界面</li><li>精通视图控制器管理与导航逻辑实现</li><li>掌握UITableView和UICollectionView的编程实现</li><li>能够使用URLSession进行网络请求与数据交互</li><li>熟练处理JSON数据，实现客户端与服务器通信</li><li>掌握Swift Concurrency（async/await）进行异步编程</li><li>精通UserDefaults、文件系统进行本地数据持久化</li><li>掌握Core Data进行复杂数据模型的管理与存储</li><li>能够设计和组织项目架构，实现模块化开发</li><li>具备调试、测试和性能优化的基础能力</li></ul><p>本书适合具备Swift语言基础，希望系统学习iOS原生开发并掌握完整技术栈的开发者。通过学习本书，您将能够独立开发功能完善、架构清晰的iOS应用，为进阶高级开发打下坚实基础。</p>',8)]))}const S=e(r,[["render",n]]);export{p as __pageData,S as default};
